{
  "root": "root_stack",
  "state": {},
  "elements": {
    "root_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg"
      },
      "children": [
        "title_h2",
        "intro_text",
        "key_considerations_stack",
        "quick_actions_h2",
        "quick_actions_stack",
        "sources_h2",
        "sources_stack"
      ]
    },
    "title_h2": {
      "type": "Text",
      "props": {
        "text": "Vancouver First-Time Home Buyer: Navigating an $800,000 CAD Budget",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Purchasing a first home in the Vancouver, BC, market with an $800,000 CAD budget presents unique challenges and requires strategic planning. While this budget may limit options within Vancouver's core, opportunities exist in various property types and surrounding municipalities. Focusing on property taxes and commute times is crucial for long-term affordability and lifestyle."
      },
      "children": []
    },
    "key_considerations_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "key_considerations_h3",
        "property_taxes_card",
        "commute_times_card",
        "property_types_card",
        "additional_financial_card"
      ]
    },
    "key_considerations_h3": {
      "type": "Text",
      "props": {
        "text": "Key Considerations for Your Vancouver Home Purchase",
        "variant": "h3"
      },
      "children": []
    },
    "property_taxes_card": {
      "type": "Card",
      "props": {},
      "children": [
        "property_taxes_header_stack",
        "property_taxes_intro_text",
        "property_taxes_grant_text",
        "property_taxes_program_text"
      ]
    },
    "property_taxes_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "property_taxes_icon",
        "property_taxes_h3"
      ]
    },
    "property_taxes_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000123_01_1_house.svg"
      },
      "children": []
    },
    "property_taxes_h3": {
      "type": "Text",
      "props": {
        "text": "Property Taxes in British Columbia",
        "variant": "h3"
      },
      "children": []
    },
    "property_taxes_intro_text": {
      "type": "Text",
      "props": {
        "text": "Property taxes in BC are calculated based on your home's assessed value and the combined municipal and provincial mill rates. For an $800,000 property, you can estimate annual property taxes to be in the range of $2,500 to $4,500, depending heavily on the specific municipality. For example, a property in Vancouver city might have a higher tax rate compared to some surrounding areas."
      },
      "children": []
    },
    "property_taxes_grant_text": {
      "type": "Text",
      "props": {
        "text": "• BC Home Owner Grant: Eligible homeowners can reduce their property tax by up to $770 (or $1,045 in northern and rural areas) if the assessed value of their home is below a certain threshold."
      },
      "children": []
    },
    "property_taxes_program_text": {
      "type": "Text",
      "props": {
        "text": "• First-Time Home Buyers' Program: You may be exempt from paying Property Transfer Tax (PTT) on a first home up to $500,000, with partial exemptions up to $525,000. For properties above this, the PTT (1% on the first $200k, 2% on the remainder up to $3M) will apply."
      },
      "children": []
    },
    "commute_times_card": {
      "type": "Card",
      "props": {},
      "children": [
        "commute_times_header_stack",
        "commute_times_intro_text",
        "translink_network_text",
        "traffic_congestion_text",
        "location_impact_text",
        "vancouver_proper_text",
        "surrounding_municipalities_text"
      ]
    },
    "commute_times_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "commute_times_icon",
        "commute_times_h3"
      ]
    },
    "commute_times_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000138_01_2_car-front.svg"
      },
      "children": []
    },
    "commute_times_h3": {
      "type": "Text",
      "props": {
        "text": "Commute Times and Transportation",
        "variant": "h3"
      },
      "children": []
    },
    "commute_times_intro_text": {
      "type": "Text",
      "props": {
        "text": "Commute times are a significant factor in Vancouver due to traffic congestion and the reliance on public transit. Your choice of location will directly impact your daily travel."
      },
      "children": []
    },
    "translink_network_text": {
      "type": "Text",
      "props": {
        "text": "• TransLink Network: Vancouver has an extensive public transit system, including SkyTrain (Expo, Millennium, Canada Lines), bus routes, and SeaBus. Living near a SkyTrain station can drastically reduce commute times to downtown Vancouver, Burnaby, New Westminster, and Surrey."
      },
      "children": []
    },
    "traffic_congestion_text": {
      "type": "Text",
      "props": {
        "text": "• Traffic Congestion: Driving during peak hours can be slow, especially on major arteries like Highway 1, Knight Street, and the Lions Gate Bridge. Consider if your workplace is easily accessible by transit or if you're comfortable with longer drive times."
      },
      "children": []
    },
    "location_impact_text": {
      "type": "Text",
      "props": {
        "text": "• Location Impact:"
      },
      "children": []
    },
    "vancouver_proper_text": {
      "type": "Text",
      "props": {
        "text": "  - Vancouver Proper: Properties within Vancouver city limits (e.g., East Van, South Vancouver) might offer shorter commutes but at a higher price point for smaller spaces."
      },
      "children": []
    },
    "surrounding_municipalities_text": {
      "type": "Text",
      "props": {
        "text": "  - Surrounding Municipalities: Areas like Burnaby, New Westminster, Richmond, Coquitlam, or Surrey often provide more affordable options within the $800,000 budget, but typically involve longer commutes, especially if driving. Many of these areas are well-served by SkyTrain."
      },
      "children": []
    },
    "property_types_card": {
      "type": "Card",
      "props": {},
      "children": [
        "property_types_header_stack",
        "property_types_intro_text",
        "condominiums_text",
        "townhouses_text",
        "detached_homes_text"
      ]
    },
    "property_types_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "property_types_icon",
        "property_types_h3"
      ]
    },
    "property_types_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000138_01_3_building.svg"
      },
      "children": []
    },
    "property_types_h3": {
      "type": "Text",
      "props": {
        "text": "Property Types and Location within Budget",
        "variant": "h3"
      },
      "children": []
    },
    "property_types_intro_text": {
      "type": "Text",
      "props": {
        "text": "With an $800,000 budget, you will primarily be looking at:"
      },
      "children": []
    },
    "condominiums_text": {
      "type": "Text",
      "props": {
        "text": "• Condominiums: These are the most common entry-level properties in Vancouver and surrounding areas. Expect to find 1 to 2-bedroom units."
      },
      "children": []
    },
    "townhouses_text": {
      "type": "Text",
      "props": {
        "text": "• Townhouses: Less common at this price point within Vancouver proper, but more feasible in areas like Surrey, Langley, or parts of Coquitlam and Burnaby."
      },
      "children": []
    },
    "detached_homes_text": {
      "type": "Text",
      "props": {
        "text": "• Detached Homes: Generally out of reach within Vancouver city and most close-in suburbs at this budget, unless they are significantly older, smaller, or located much further from the city center."
      },
      "children": []
    },
    "additional_financial_card": {
      "type": "Card",
      "props": {},
      "children": [
        "additional_financial_header_stack",
        "additional_financial_intro_text",
        "strata_fees_text",
        "closing_costs_text",
        "utilities_insurance_text"
      ]
    },
    "additional_financial_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "additional_financial_icon",
        "additional_financial_h3"
      ]
    },
    "additional_financial_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000124_01_1_currency-dollar.svg"
      },
      "children": []
    },
    "additional_financial_h3": {
      "type": "Text",
      "props": {
        "text": "Additional Financial Considerations",
        "variant": "h3"
      },
      "children": []
    },
    "additional_financial_intro_text": {
      "type": "Text",
      "props": {
        "text": "Beyond the purchase price and property taxes, factor in:"
      },
      "children": []
    },
    "strata_fees_text": {
      "type": "Text",
      "props": {
        "text": "• Strata Fees: For condos and townhouses, these monthly fees cover building maintenance, insurance, and amenities. They can range from $200 to $600+ per month."
      },
      "children": []
    },
    "closing_costs_text": {
      "type": "Text",
      "props": {
        "text": "• Closing Costs: Include legal fees, property transfer tax (if applicable), and title insurance, typically 1-3% of the purchase price."
      },
      "children": []
    },
    "utilities_insurance_text": {
      "type": "Text",
      "props": {
        "text": "• Utilities and Insurance: Budget for monthly utility bills (electricity, heating, internet) and home insurance."
      },
      "children": []
    },
    "quick_actions_h2": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "property_tax_button",
        "commute_planner_button",
        "homes_for_sale_button"
      ]
    },
    "property_tax_button": {
      "type": "Button",
      "props": {
        "label": "Estimate Property Taxes: BC Property Tax Info"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www2.gov.bc.ca/gov/content/taxes/property-taxes"
          }
        }
      },
      "children": []
    },
    "commute_planner_button": {
      "type": "Button",
      "props": {
        "label": "Plan Your Commute: TransLink Trip Planner"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.translink.ca/"
          }
        }
      },
      "children": []
    },
    "homes_for_sale_button": {
      "type": "Button",
      "props": {
        "label": "Explore Homes for Sale: Search on Realtor.ca"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.realtor.ca/"
          }
        }
      },
      "children": []
    },
    "sources_h2": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "bc_gov_property_taxes_button",
        "translink_source_button",
        "realtor_ca_source_button"
      ]
    },
    "bc_gov_property_taxes_button": {
      "type": "Button",
      "props": {
        "label": "BC Government Property Taxes"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www2.gov.bc.ca/gov/content/taxes/property-taxes"
          }
        }
      },
      "children": []
    },
    "translink_source_button": {
      "type": "Button",
      "props": {
        "label": "TransLink"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.translink.ca/"
          }
        }
      },
      "children": []
    },
    "realtor_ca_source_button": {
      "type": "Button",
      "props": {
        "label": "Realtor.ca"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.realtor.ca/"
          }
        }
      },
      "children": []
    }
  }
}
